(()=>{
const c=window.BoraCourses[0];
const add=(id,title,scene,idea,examples,q1,q2,write,mission,topic,why,mistake)=>c.lessons.push({id,title,scene,idea,examples,quiz:[q1,q2],write,mission,topic,why,mistake});
add('ter','Сказать, что у тебя есть','Сосед спрашивает о твоей семье и возрасте.','Ter — «иметь», но по-русски обычно «у меня есть». Eu tenho — у меня есть; você tem — у тебя есть. Возраст тоже выражают через ter: tenho trinta anos — мне тридцать лет. Не переноси русское «мне» дословно.',[['Eu tenho um irmão.','У меня есть брат.'],['Você tem tempo?','У тебя есть время?'],['Eu tenho trinta anos.','Мне тридцать лет.']],['Вставь: Eu ___ um irmão.',['tenho','sou','estou'],0,'У меня есть: eu tenho.'],['Как спросить, есть ли время?',['Você tem tempo?','Você é tempo?','Você está tempo?'],0,'С você используем tem.'],['Вставь: Eu ___ vinte anos.',['tenho'],'tenho'],'Расскажи о возрасте и одном предмете, который у тебя есть.','Ter и возраст','Португальский описывает возраст как то, что у тебя есть: tenho ... anos. Это языковая привычка, а не универсальная логика.','Eu sou vinte anos неверно для возраста. Нужен tenho.');
add('gostar','Рассказать, что нравится','Новый друг спрашивает о твоих увлечениях.','Gostar de — «любить / нравиться». Eu gosto de café — мне нравится кофе. После gostar нужен маленький мостик de. С действием тоже de: gosto de estudar. Если дальше известный предмет с артиклем, de соединяется с ним: de + o = do.',[['Eu gosto de café.','Мне нравится кофе.'],['Eu gosto de estudar português.','Мне нравится изучать португальский.'],['Você gosta de música?','Тебе нравится музыка?']],['Выбери естественную фразу.',['Eu gosto de café.','Eu gosto café.','Eu sou gosto café.'],0,'После gostar ставим de.'],['Вставь: Ela ___ de música.',['gosta','gosto','gostar'],0,'С ela форма gosta.'],['Вставь: Eu gosto ___ estudar.',['de'],'de'],'Напиши, что тебе нравится и что не нравится. Спроси об этом друга.','Gostar de','Глаголы могут требовать определённый предлог. Здесь de — часть модели gostar de, её удобнее учить целиком.','Не пропускай de и не добавляй sou перед gosto.');
add('horas','Договориться о времени','Нужно согласовать время встречи.','Для одного часа: é uma hora. Для двух и дальше: são duas horas. Чтобы сказать «в восемь», используем às oito; «в час» — à uma. Meio-dia — полдень. Время встречи удобно подтвердить коротким сообщением.',[['São duas horas.','Сейчас два часа.'],['A reunião é às oito.','Встреча в восемь.'],['Pode ser às nove?','Можно в девять?']],['Выбери «Сейчас два часа».',['São duas horas.','É duas horas.','Tenho duas horas agora.'],0,'Duas horas — множественное число, поэтому são.'],['Às oito означает…',['в восемь','вчера','восьмой дом'],0,'Às вводит время события.'],['Напиши число словом: às ___ (в девять).',['nove'],'nove'],'Предложи другу время встречи и спроси, подходит ли оно.','Часы и расписание','Às образуется из предлога a и артикля as. Для начала запомни готовую модель às + часы.','Сравни: são duas horas — сейчас два; às duas — в два.');
add('familia','Рассказать о близких','Ты показываешь фотографию семьи.','Meu/minha — «мой/моя»; seu/sua — «твой/твоя» или «его/её» по контексту. Выбираем форму по предмету: meu irmão, minha irmã. Пол владельца не определяет окончание. Для ясности его/её можно сказать dele/dela.',[['Minha irmã mora aqui.','Моя сестра живёт здесь.'],['Meu pai trabalha em São Paulo.','Мой отец работает в Сан-Паулу.'],['Este é o carro dela.','Это её машина.']],['Как сказать «моя сестра»?',['minha irmã','meu irmã','minha irmão'],0,'Irmã — женский род: minha.'],['Dela уточняет…',['её','их','нас'],0,'De + ela = dela.'],['Вставь: ___ irmão (мой брат).',['meu','o meu'],'meu'],'Опиши двух близких: кто они и где живут. Можно придумать семью.','Притяжательные слова','Minha согласуется с irmã, а не с человеком, который говорит.','Seu бывает неоднозначным. Если непонятно, чей предмет, используй dele или dela.');
add('compras','Купить нужное и уточнить оплату','Ты выбираешь футболку в магазине.','Quero — хочу, queria — в просьбе более мягкое «я хотел бы». Tem ...? часто означает «У вас есть ...?». Для цвета и размера: uma camiseta azul, tamanho M. В Бразилии спрашивают Aceita Pix? — принимаете Pix? Не нужно сообщать реальные платёжные данные для упражнения.',[['Tem uma camiseta azul?','У вас есть синяя футболка?'],['Quanto custa?','Сколько стоит?'],['Aceita Pix?','Принимаете Pix?']],['Как спросить цену?',['Quanto custa?','Onde custa?','Quando cor?'],0,'Quanto — сколько.'],['Tem tamanho M? означает…',['Есть размер M?','Сколько времени?','Где рынок?'],0,'В магазине tem спрашивает о наличии.'],['Вставь: Quanto ___? (Сколько стоит?)',['custa'],'custa'],'Разыграй покупку: наличие, размер, цена и способ оплаты.','Покупки и уточнения','В разговоре tem часто используется без названного подлежащего, когда понятно, что речь о наличии товара.','Вопрос Quanto custa? — о цене, Onde fica? — о месте.');
add('poder','Попросить о помощи','Ты не понял, что сказал сотрудник.','Posso — «я могу / можно мне», pode — «ты можешь / можете». После этой формы второй глагол остаётся начальным: pode repetir. Preciso de ajuda — мне нужна помощь; preciso falar — мне нужно поговорить. С существительным здесь de, с действием — без de.',[['Pode repetir, por favor?','Можете повторить, пожалуйста?'],['Pode falar mais devagar?','Можете говорить медленнее?'],['Preciso de ajuda.','Мне нужна помощь.']],['Что сказать, если не понял?',['Pode repetir, por favor?','Eu repeti ontem.','Nunca ajuda.'],0,'Повторить — repetir.'],['Выбери правильную модель.',['Preciso de ajuda.','Preciso ajuda de.','Sou preciso ajuda.'],0,'Нужна помощь: preciso de ajuda.'],['Вставь: Pode ___ mais devagar? (говорить)',['falar'],'falar'],'Попроси повторить фразу, затем говорить медленнее и объяснить одно слово.','Poder и precisar','После pode стоит инфинитив: форму лица уже несёт первый глагол.','Pode fala — ошибка в этой модели. Нужен falar.');
add('saude','Объяснить самочувствие','Ты записываешься к врачу.','Estou com dor de cabeça — у меня болит голова. Для состояния пригодятся estou com febre и estou cansado/cansada. Preciso marcar uma consulta — нужно записаться на приём. Урок тренирует речь, а не даёт медицинские рекомендации.',[['Estou com dor de cabeça.','У меня болит голова.'],['Preciso marcar uma consulta.','Мне нужно записаться на приём.'],['Tem horário amanhã?','Есть свободное время завтра?']],['Как сказать о боли в голове?',['Estou com dor de cabeça.','Sou uma cabeça.','Tenho ontem cabeça.'],0,'Готовая модель: estar com dor de...'],['Marcar uma consulta — это…',['записаться на приём','купить билет','поговорить о погоде'],0,'Consulta — приём / консультация.'],['Вставь: Estou ___ dor de cabeça.',['com'],'com'],'Составь короткое сообщение: симптом, просьба записать, удобный день.','Самочувствие и запись','Com буквально «с», но всё сочетание по-русски переводится естественно: у меня болит голова.','Не переводи каждое слово отдельно: учи estou com dor как готовую модель.');
add('telefone','Уточнить сообщение и договориться','Друг написал в WhatsApp, но план неясен.','Pode me mandar o endereço? — можешь прислать мне адрес? Me указывает получателя действия: мне / меня. В живой бразильской речи me часто стоит перед глаголом. Для короткой переписки важны цель, время и подтверждение.',[['Pode me mandar o endereço?','Можешь прислать мне адрес?'],['A gente se encontra às oito.','Встретимся в восемь.'],['Combinado!','Договорились!']],['Зачем здесь me: pode me mandar?',['Обозначает получателя: мне','Означает завтра','Делает слово множественным'],0,'Mandar algo para mim — прислать что-то мне.'],['Combinado! в переписке — это…',['Договорились!','Я потерялся!','До вчера!'],0,'Так подтверждают договорённость.'],['Напиши по-португальски «Договорились!».',['combinado'],'Combinado!'],'Напиши другу: уточни место, предложи время и подтверди договорённость.','Переписка и me','В Бразилии a gente означает «мы», но требует форму 3-го лица единственного: a gente se encontra.','A gente se encontramos смешивает две модели. Либо nós nos encontramos, либо a gente se encontra.');
add('passado','Рассказать о завершённом действии','Друг спрашивает, как прошёл день.','Вчерашние завершённые действия: eu trabalhei, você trabalhou. У глаголов на -ar появляются окончания -ei / -ou. Частые формы лучше узнавать отдельно: eu fiz — сделал, eu tive — у меня было, eu fui — пошёл / был. Контекст объясняет, что именно означает fui.',[['Ontem eu trabalhei.','Вчера я работал.'],['Eu fiz o jantar.','Я приготовил ужин.'],['Ela chegou cedo.','Она пришла рано.']],['Выбери «Я вчера работал».',['Ontem eu trabalhei.','Ontem eu trabalho amanhã.','Ontem trabalhar eu.'],0,'Trabalhei — завершённое действие с eu.'],['Eu fiz o jantar означает…',['Я приготовил ужин','Я приготовлю завтра','Я всегда голоден'],0,'Fiz — прошедшая форма fazer.'],['Вставь: Ontem eu ___ (работал).',['trabalhei'],'trabalhei'],'Напиши три события вчерашнего дня с ontem, depois и à noite.','Завершённое прошлое','Для рассказа о событии говорящий выбирает его как завершённый эпизод: вчера сделал, пришёл, сходил.','Не добавляй sou перед trabalhei. Лицо и время уже выражены в глаголе.');
add('imperfeito','Различить событие и привычку','Ты рассказываешь, как жил раньше.','Eu morava — я жил раньше / обычно жил. Eu morei — я пожил, речь об ограниченном периоде. Imperfeito часто задаёт привычку или фон, а perfeito — событие на этом фоне. Это не буквальное соответствие русским видам глагола: смотри на смысл истории.',[['Quando era criança, eu brincava na rua.','В детстве я играл на улице.'],['Eu morava em Moscou.','Раньше я жил в Москве.'],['Estava chovendo quando ele chegou.','Шёл дождь, когда он пришёл.']],['Выбери фон: «Когда я был ребёнком…»',['Quando eu era criança…','Quando eu fui amanhã…','Quando eu sou ontem…'],0,'Era задаёт состояние в прошлом.'],['Chegou в истории с дождём — это…',['событие на фоне дождя','ежедневная привычка','будущий план'],0,'Дождь — фон, приход — событие.'],['Вставь: Antes eu ___ em Moscou. (жил, morava)',['morava'],'morava'],'Расскажи о прежней привычке и одном конкретном событии.','Фон и привычки в прошлом','Выбор времени показывает, как говорящий рассматривает прошлое: изнутри как фон или целиком как эпизод.','Не определяй время только по слову ontem: важен смысл всей фразы.');
add('comparar','Сравнить два варианта','Ты выбираешь транспорт и жильё.','Mais ... que — «более ... чем», menos ... que — «менее ... чем». Tão ... quanto — «такой же ... как». У bom есть обычная сравнительная форма melhor — лучше; у ruim — pior, хуже. Сравнивай по конкретному признаку: цене, расстоянию, удобству.',[['O ônibus é mais barato que o táxi.','Автобус дешевле такси.'],['Este apartamento é menor.','Эта квартира меньше.'],['O metrô é melhor para mim.','Метро лучше для меня.']],['Выбери «лучше».',['melhor','mais bom','muito ontem'],0,'Обычная сравнительная форма bom — melhor.'],['Mais barato que означает…',['дешевле, чем','такой же большой','очень далеко'],0,'Barato — дешёвый.'],['Вставь: mais barato ___ o táxi.',['que','do que'],'que'],'Сравни два способа добраться домой и объясни свой выбор.','Сравнения','Две части сравнения связываются que или do que: mais barato que/do que.','Mais bom обычно заменяется melhor. Не пытайся образовать все сравнения одним шаблоном.');
add('condicional','Попросить мягче и представить возможность','Ты хочешь попросить услугу у незнакомого человека.','Poderia — мог бы; gostaria de — хотел бы. Эти формы делают просьбу менее прямой: Você poderia me ajudar? Для воображаемого результата: eu viajaria — я бы поехал. Начни с полезных готовых просьб, затем переходи к условиям.',[['Você poderia me ajudar?','Вы могли бы мне помочь?'],['Eu gostaria de uma informação.','Я хотел бы кое-что узнать.'],['Eu viajaria mais.','Я бы путешествовал больше.']],['Выбери мягкую просьбу.',['Você poderia me ajudar?','Você ajudou ontem.','Você ajuda nunca.'],0,'Poderia смягчает просьбу.'],['После gostaria обычно ставится…',['de','em','com ontem'],0,'Модель: gostaria de + предмет или действие.'],['Вставь: Eu gostaria ___ um café.',['de'],'de'],'Попроси информацию о расписании вежливо двумя разными способами.','Вежливость и условность','Форма «могли бы» не требует, чтобы речь шла о прошлом: здесь это дистанция и вежливость.','Gostaria um café пропускает de.');
add('conectores','Связать мысли в короткий рассказ','Ты объясняешь другу, почему изменил планы.','Porque объясняет причину, por isso — результат. Mas/porém показывают противопоставление. Embora вводит уступку и обычно требует subjuntivo: embora seja ... — хотя это ... . Начни с коротких предложений и одного точного связующего слова.',[['Estava chovendo, por isso fiquei em casa.','Шёл дождь, поэтому я остался дома.'],['Quero ir, mas não posso.','Хочу пойти, но не могу.'],['Embora seja curto, o curso é útil.','Хотя курс короткий, он полезный.']],['Por isso связывает…',['причину с результатом','имя с возрастом','время с числом'],0,'Было условие — поэтому получился результат.'],['Выбери «но».',['mas','porque','amanhã'],0,'Mas вводит противопоставление.'],['Вставь: Não fui ___ estava cansado. (потому что)',['porque'],'porque'],'Объясни изменение планов: причина, результат и одно противопоставление.','Причина, результат и уступка','Союз показывает связь мыслей слушателю. Сначала выбери эту связь, потом слово.','Porque — причина; por isso — следствие. Они не взаимозаменяемы.');
add('opiniao','Выразить мнение с аргументом','Ты обсуждаешь жизнь в городе.','Na minha opinião — по моему мнению; acho que — думаю, что. Хороший короткий ответ: позиция, причина, пример. Можно признать другую сторону: por outro lado — с другой стороны. Не нужно начинать каждую фразу с одного и того же оборота.',[['Acho que o transporte melhorou.','Думаю, транспорт стал лучше.'],['Na minha opinião, precisamos de mais ônibus.','По-моему, нам нужно больше автобусов.'],['Por outro lado, o metrô é rápido.','С другой стороны, метро быстрое.']],['Что добавляет потому что к мнению?',['аргумент','только время','имя собеседника'],0,'Причина помогает понять твою позицию.'],['Acho que означает…',['Я думаю, что','Я точно был вчера','Пожалуйста, повтори'],0,'Это обычный способ выразить мнение.'],['Вставь: Na minha ___ (по моему мнению).',['opiniao'],'opinião'],'Напиши 4–5 предложений: удобно ли жить в твоём городе? Позиция, причина, пример, оговорка.','Мнение и аргумент','Связная речь — это отношения между мыслями, а не просто более длинные предложения.','Acho que — мнение, а не гарантия достоверности факта.');
add('subjuntivo','Говорить о возможном будущем','Ты планируешь день, но не уверен, будет ли время.','После se о возможном будущем: se eu tiver tempo — если у меня будет время. После quando о будущем: quando eu chegar — когда приду. В главной части удобно vou + глагол. Не путай с воображаемым условием: se eu tivesse ... — если бы у меня было ... .', [['Se eu tiver tempo, vou estudar.','Если будет время, я позанимаюсь.'],['Quando eu chegar, vou ligar.','Когда приеду, позвоню.'],['Se chover, vou ficar em casa.','Если пойдёт дождь, я останусь дома.']],['Выбери возможное будущее.',['Se eu tiver tempo, vou estudar.','Se eu tenho ontem, fui.','Se eu sou tempo, estudar.'],0,'Возможное условие в будущем: se tiver.'],['Quando eu chegar относится…',['к будущему прибытию','к имени','к вчерашней покупке'],0,'Chegar здесь — форма будущего subjuntivo.'],['Вставь: Se eu ___ tempo amanhã… (ter)',['tiver'],'tiver'],'Составь два плана: что сделаешь, если будет время, и когда вернёшься домой.','Будущее subjuntivo','У регулярных глаголов эта форма часто выглядит как инфинитив, но у ter — tiver. Поэтому одной внешней формы недостаточно.','Se eu teria не используется здесь вместо se eu tiver.');
add('email','Написать полезное письмо','Нужно попросить перенести занятие.','Перед письмом реши: кому пишешь, зачем и что получатель должен сделать. Вежливое начало Olá, затем причина и конкретная просьба. Укажи дату или время, заверши благодарностью. Важнее понятная задача, чем сложная грамматика.', [['Olá, gostaria de remarcar a aula.','Здравствуйте, я хотел бы перенести занятие.'],['Podemos marcar para sexta-feira?','Можно назначить на пятницу?'],['Obrigado pela atenção.','Спасибо за внимание.']],['Что обязательно для письма с просьбой?',['Понятная просьба и нужные подробности','Только длинное приветствие','Список всех знакомых слов'],0,'Получатель должен понимать следующее действие.'],['Remarcar a aula — это…',['перенести занятие','начать обед','оплатить такси'],0,'Remarcar — назначить заново.'],['Вставь: Obrigado ___ atenção.',['pela'],'pela'],'Напиши письмо из 5–7 предложений: перенеси занятие, объясни причину, предложи день. Не указывай личные данные.','Письменная коммуникация','Одна и та же информация меняется по адресату: другу короче, учреждению — яснее и вежливее.','Не забудь саму просьбу: описание проблемы без неё может оставить читателя без следующего шага.');
add('resumo','Передать главное своими словами','Друг просит объяснить короткое объявление.','Чтобы пересказать сообщение, найди кто, что, когда и для кого. Оставь только сведения, которые нужны слушателю. Не добавляй факты от себя. Затем проверь: сохранились ли дата, действие и причина? Это подготовка к работе с информацией, а не полный пробник экзамена.', [['A biblioteca fecha às seis hoje.','Сегодня библиотека закрывается в шесть.'],['O atendimento volta amanhã.','Обслуживание возобновится завтра.'],['É preciso levar um documento.','Нужно взять документ.']],['«A biblioteca fecha às seis hoje.» Что обязательно сохранить?',['Библиотека сегодня закрывается в 18:00','Библиотека закрыта навсегда','Книги сегодня бесплатные'],0,'Не меняем время и не придумываем новые факты.'],['Зачем учитывать адресата пересказа?',['Чтобы выбрать нужные ему сведения','Чтобы добавить выдуманную историю','Чтобы скрыть время'],0,'Пересказ должен решать задачу слушателя.'],['Вставь: O atendimento volta ___. (завтра)',['amanha'],'amanhã'],'Объявление: «A biblioteca fecha às seis hoje. O atendimento volta amanhã às nove.» Напиши другу 2–3 предложения: когда лучше прийти.','Чтение и передача смысла','Пересказ проверяет понимание связей, а не способность скопировать исходный текст.','Не превращай hoje в sempre: временное изменение не означает постоянное.');
add('conversa','Поддержать разговор и уточнить','Собеседник говорит быстро, а тебе нужно продолжить беседу.','Разговор держится на реакции и уточнении. Entendi — понял; quer dizer que...? — ты имеешь в виду, что...? E você? возвращает вопрос. Если не понял, попроси переформулировать. Можно пересказать услышанное и проверить смысл, вместо того чтобы молча соглашаться.', [['Entendi. E você?','Понял. А ты?'],['Quer dizer que a reunião mudou?','Ты имеешь в виду, что встречу перенесли?'],['Pode explicar de outro jeito?','Можешь объяснить по-другому?']],['Что сделать, если смысл неясен?',['Попросить уточнить и проверить понимание','Автоматически согласиться','Сразу сменить язык наугад'],0,'Уточнение — нормальная часть общения.'],['De outro jeito означает…',['по-другому','вчера','без человека'],0,'Это просьба переформулировать.'],['Вставь: Pode explicar de outro ___?',['jeito'],'jeito'],'Попроси помощника сыграть бразильского соседа: обсудите встречу, задай два уточняющих вопроса и подведи итог договорённости.','Стратегии общения','Умение заметить непонимание и исправить его помогает общаться даже с небольшим запасом слов.','Фраза Entendi означает, что ты понял. Если сомневаешься, лучше уточни.');
c.title='Бразильский португальский: от первых фраз к общению';c.description='30 уроков: знакомство, жизнь в Бразилии, прошлое и планы, связная речь и первые письменные задачи.';
const order=['oi','nome','origem','estar','artigos','nao','ter','familia','rotina','gostar','numeros','horas','cafe','compras','onde','poder','saude','telefone','amanha','ontem','passado','imperfeito','comparar','condicional','conectores','opiniao','subjuntivo','email','resumo','conversa'];c.lessons.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
const groups=[['Первые фразы',0,6],['Повседневная жизнь',6,12],['Самостоятельность в Бразилии',12,18],['Истории и планы',18,24],['Связная речь и письменные задачи',24,30]];
c.modules=groups.map(([title,start,end])=>({title,lessons:c.lessons.slice(start,end).map(l=>l.id)}));
for(const l of c.lessons){l.module=c.modules.find(m=>m.lessons.includes(l.id)).title;l.goal=l.mission;l.review='Закрой примеры и объясни правило своими словами. Затем скажи одну новую фразу о себе. Повтори завтра и через три дня.';l.why||=l.idea;l.mistake||='Не переводи фразу слово в слово с русского. Найди в примере готовую модель и замени только нужную часть.';l.dialogue=[l.examples[0][0],l.examples[1][0]];}
})();
// Extra explanations for the first steps: avoid replacing a rule with another rule.
(()=>{const details={
oi:['Вопрос и ответ могут состоять из одинаковых слов: Tudo bem? / Tudo bem. Разницу слышно по интонации и видно по знаку вопроса.','Obrigado/obrigada — спасибо; это не ответ на вопрос «как дела».'],
nome:['Sou — форма ser с eu. По-русски связка «есть» обычно опускается, в португальском она остаётся. Перед именем артикль возможен, но его употребление зависит от региона.','Для имени говорим sou, а не estou. Eu sou Ana и Eu sou a Ana могут быть естественными.'],
origem:['De задаёт происхождение. С артиклем он соединяется: de + a = da, de + o = do. У названий городов и стран привычки разные: de Moscou, da Rússia, do Brasil.','Не пытайся ставить da перед всеми странами и городами. Учи название вместе с предлогом.'],
estar:['Ser связывает с идентичностью или признаком, estar описывает состояние или местонахождение человека. «Постоянное / временное» — полезная подсказка, но не полное правило: событие бывает с ser, например a reunião é aqui.','Не выбирай глагол только по длительности. Eu sou brasileiro, eu estou cansado — две разные функции.'],
artigos:['Артикль помогает показать, о каком предмете речь: um livro вводит книгу, o livro указывает на понятную из контекста книгу. Род — свойство слова; его удобнее запоминать сразу с o или a.','A casa — не «этот дом» во всех контекстах. Иногда по-русски это просто «дом», а нужный предмет понятен собеседникам.'],
nao:['В простом отрицании não ставится перед глаголом. Вопрос в разговоре часто сохраняет порядок слов, а меняется интонация: Você fala português?','Не нужен дополнительный глагол как английский do: Você fala? — уже вопрос.'],
rotina:['Основа сохраняет значение действия, окончание связывает его с лицом: eu trabalho, você trabalha, nós trabalhamos. В Бразилии a gente часто заменяет nós и требует форму trabalha.','Eu trabalho — самостоятельное предложение. Eu sou trabalho не означает «я работаю».'],
numeros:['Цена — число плюс название валюты: dois reais. У real множественное число reais. На ценниках запятая обычно отделяет копейки: 2,50.','Dois reais — два реала, а не два часа. Для цены спрашивают quanto, для времени — que horas.'],
cafe:['В коротком заказе пропуски понятны из ситуации: um café, por favor. Quero прямо выражает желание; gostaria de — мягче. Вежливость зависит также от тона и контекста.','Por favor — в просьбе; obrigado/obrigada — благодарность. Это разные моменты разговора.'],
onde:['Onde задаёт вопрос о месте. Fica часто описывает расположение: Onde fica a farmácia? Perto/longe — близко/далеко, à direita/à esquerda — направо/налево.','Где? — onde. Куда идёшь? — para onde você vai? Выбирай вопрос по смыслу.'],
amanha:['В vou estudar первое слово показывает лицо и настоящее намерение, второе называет действие. Это обычная модель будущего в разговоре.','Не меняй второй глагол: vou estudar, а не vou estudo.'],
ontem:['Fui может происходить от ir и ser. Eu fui ao mercado — я сходил на рынок; eu fui professor — я был учителем. Окружение слова помогает понять значение.','Вчера не всегда требует fui: действие «работал» выражается trabalhei. Выбирай сам нужный глагол.']};for(const l of window.BoraCourses[0].lessons){if(details[l.id])[l.why,l.mistake]=details[l.id]}})();
